fn hermemulx(c: Vec<f64>) -> Vec<f64> {
    // Pre-allocate output of length one greater than the input
    let mut result = Vec::with_capacity(c.len() + 1);
    // First element is always 0.0
    result.push(0.0);
    // Then append all elements of c in order
    result.extend_from_slice(&c);
    result
}

